package android.content.pm;
public class Signature { byte[] b; public Signature(byte[] b) { this.b = b; } public Signature(String s) { int n = s.length() / 2; b = new byte[n]; for (int i = 0; i < n; i++) b[i] = (byte) Integer.parseInt(s.substring(2 * i, 2 * i + 2), 16); } public boolean equals(Object o) { return o instanceof Signature && java.util.Arrays.equals(b, ((Signature) o).b); } public byte[] toByteArray() { return b; } public String toCharsString() { StringBuilder s = new StringBuilder(); for (byte x : b) s.append(String.format("%02x", x)); return s.toString(); } public int hashCode() { return java.util.Arrays.hashCode(b); } }